128.    * Async checkout pipeline:
129.    *  1. Refresh prices via the (optional) `priceFetcher`.
130.    *  2. Validate inventory via the (optional) `inventoryChecker`; first denial
131.    *     wins and throws an :class:`InventoryError` describing the failing line.
132.    *  3. Compute totals; if an `asyncTaxProvider` is supplied, the tax calculator
133.    *     is replaced for this call by an :class:`AsyncTaxCalculator`.
134.    */
135.   async checkout(collaborators: CheckoutCollaborators = {}): Promise<CheckoutResult> {
136.     let lines = this.snapshot();
137.     if (collaborators.priceFetcher) {
138.       lines = await refreshPrices(lines, collaborators.priceFetcher);
139.     }
140.     if (collaborators.inventoryChecker) {
141.       for (const line of lines) {
142.         const decision = await collaborators.inventoryChecker.check(
143.           line.product.id,
144.           line.quantity,
145.         );
146.         const available = decision.availableQuantity;
147.         if (!decision.available || (available !== undefined && available < line.quantity)) {
148.           throw new InventoryError(
149.             decision.reason ??
150.               `insufficient stock for ${line.product.id}: requested ${line.quantity}, available ${available ?? 0}`,
151.             line.product.id,
152.             line.quantity,
153.             available,
154.           );
155.         }
156.       }
157.     }
158.     const totals = collaborators.asyncTaxProvider
159.       ? await this.computeTotalsAsync(lines, collaborators.asyncTaxProvider)
160.       : this.computeTotals(lines);
161.     return { totals, lines };
162.   }
163. 
164.   private computeSubtotal(lines: readonly CartLine[]): number {
165.     let total = 0;
166.     for (const line of lines) {
167.       total += line.product.unitPriceCents * line.quantity;
168.     }
169.     return total;
170.   }
171. 
172.   private clampDiscount(subtotalCents: number): number {
173.     return Math.min(
174.       Math.max(0, this.discountPolicy.computeDiscountCents(subtotalCents)),
175.       subtotalCents,
176.     );
177.   }
178. 
179.   private computeTotals(lines: readonly CartLine[]): CartTotals {
180.     const subtotalCents = this.computeSubtotal(lines);
181.     const discountCents = this.clampDiscount(subtotalCents);
182.     const discountedSubtotal = subtotalCents - discountCents;
183.     const taxCents = Math.max(
184.       0,
185.       this.taxCalculator.computeTaxCents(discountedSubtotal, this.region),
186.     );
187.     const shippingCents = Math.max(
188.       0,
189.       this.shippingCalculator.computeShippingCents(lines, discountedSubtotal),
190.     );
191.     return {
192.       subtotalCents,
193.       discountCents,
194.       taxCents,
195.       shippingCents,
196.       totalCents: discountedSubtotal + taxCents + shippingCents,
197.     };
198.   }
199. 
200.   private async computeTotalsAsync(
201.     lines: readonly CartLine[],
202.     provider: AsyncTaxRateProvider,
203.   ): Promise<CartTotals> {
204.     const subtotalCents = this.computeSubtotal(lines);
205.     const discountCents = this.clampDiscount(subtotalCents);
206.     const discountedSubtotal = subtotalCents - discountCents;
207.     const asyncTax = new AsyncTaxCalculator(provider);
208.     const taxCents = Math.max(
209.       0,
210.       await asyncTax.computeTaxCents(discountedSubtotal, this.region),
211.     );
212.     const shippingCents = Math.max(
213.       0,
214.       this.shippingCalculator.computeShippingCents(lines, discountedSubtotal),
215.     );
216.     return {
217.       subtotalCents,
218.       discountCents,
219.       taxCents,
220.       shippingCents,
