      expect(sut.computeShippingCents(emptyLines, 100)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 10.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 10.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 600 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("selects the first bracket that fits", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      // 400g ≤ 500
      expect(sut.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });

    it("exact boundary matches the bracket", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("just over boundary picks next bracket", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
    });

    it("picks the heaviest bracket for weight at top boundary", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(
        1200,
      );
    });

    it("falls back to heaviest bracket cost when no overflow is set", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(
        1200,
      );
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const sut = new WeightBasedShippingCalculator(brackets, 2000);
      expect(sut.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(
        2000,
      );
    });

    it("returns 0 for empty cart", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      expect(sut.computeShippingCents(emptyLines, 1000)).toBe(0);
    });

    it("returns 0 when total weight is zero", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 1 },
      ];
      expect(sut.computeShippingCents(lines, 1000)).toBe(0);
    });

    it("sums weights across multiple lines with quantity", () => {
      const sut = new WeightBasedShippingCalculator(brackets);
      // 2 x 300g = 600g → bracket 2000
      expect(sut.computeShippingCents([makeLine("a", 300, 2)], 1000)).toBe(
        600,
      );
    });

    it("sorts unsorted brackets correctly", () => {
      const unsorted = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 600 },
      ];
      const sut = new WeightBasedShippingCalculator(unsorted);
      expect(sut.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
