describe("refreshPrices", () => {
  const makeLines = (): CartLine[] => [
    { product: { id: "p1", name: "Widget", unitPriceCents: 100 }, quantity: 2 },
    { product: { id: "p2", name: "Gadget", unitPriceCents: 200, weightGrams: 500 }, quantity: 1 },
  ];

  it("updates unitPriceCents from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(150)
        .mockResolvedValueOnce(250),
    };
    const result = await refreshPrices(makeLines(), fetcher);
    expect(result[0].product.unitPriceCents).toBe(150);
    expect(result[1].product.unitPriceCents).toBe(250);
  });

  it("preserves other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };
    const result = await refreshPrices(makeLines(), fetcher);
    expect(result[1].product.weightGrams).toBe(500);
    expect(result[0].product.name).toBe("Widget");
  });

  it("preserves quantity", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };
    const result = await refreshPrices(makeLines(), fetcher);
    expect(result[0].quantity).toBe(2);
  });

  it("calls fetcher with correct product ids", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(100),
    };
    await refreshPrices(makeLines(), fetcher);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p1");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("p2");
  });

  it("throws RangeError for negative price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("throws RangeError for non-integer price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      RangeError,
    );
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
    };
    await expect(refreshPrices(makeLines(), fetcher)).rejects.toThrow(
      "fetch failed",
    );
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const result = await refreshPrices([], fetcher);
    expect(result).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

// ── Helpers ──────────────────────────────────────────────────────
const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

function makeDiscountPolicy(fn: (s: number) => number): DiscountPolicy {
  return { computeDiscountCents: vi.fn(fn) };
}
function makeTaxCalculator(fn: (t: number, r: string) => number): TaxCalculator {
  return { computeTaxCents: vi.fn(fn) };
}
function makeShippingCalculator(fn: (l: readonly any[], s: number) => number): ShippingCalculator {
  return { computeShippingCents: vi.fn(fn) };
}

// ── Cart line management ─────────────────────────────────────────
describe("Cart line management", () => {
  it("adds a product and reports correct itemCount", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when the same product is added twice", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("tracks separate products independently", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    expect(cart.itemCount).toBe(3);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it("rejects zero quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
  });

  it("rejects negative quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });
});

describe("Cart.remove", () => {
  it("removes an existing product and returns true", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
