    expect(cart.totals().subtotalCents).toBe(2000);
  });
});

// ── Pricing pipeline ─────────────────────────────────────────────
describe("Cart.totals() pricing pipeline", () => {
  it("computes subtotal as sum of (price × qty)", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2 × 1000
    cart.add(gadget, 1); // 1 × 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("applies discount then tax on discounted subtotal", () => {
    const discount = makeDiscountPolicy(() => 500);
    const tax = makeTaxCalculator((taxable) => Math.floor(taxable * 0.1));
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(widget, 2); // subtotal 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // tax on 1500 at 10% = 150
    expect(totals.taxCents).toBe(150);
  });

  it("clamps discount to [0, subtotal] — negative discount becomes 0", () => {
    const discount = makeDiscountPolicy(() => -100);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount to [0, subtotal] — over-subtotal discount capped", () => {
    const discount = makeDiscountPolicy(() => 99999);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const tax = makeTaxCalculator(() => -50);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping = makeShippingCalculator(() => -50);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("passes discounted subtotal to shipping calculator", () => {
    const discount = makeDiscountPolicy(() => 300);
    const shippingFn = vi.fn(() => 500);
    const shipping: ShippingCalculator = {
      computeShippingCents: shippingFn,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(widget, 1); // subtotal 1000, discounted = 700
    cart.totals();
    expect(shippingFn).toHaveBeenCalledWith(expect.any(Array), 700);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount = makeDiscountPolicy(() => 200);
    const tax = makeTaxCalculator(() => 80);
    const shipping = makeShippingCalculator(() => 500);
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(widget, 1); // subtotal 1000
    const totals = cart.totals();
    // discounted = 800, total = 800 + 80 + 500 = 1380
    expect(totals.totalCents).toBe(1380);
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses defaults when no config is provided", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const totals = cart.totals();
    // NoDiscount, NoTax, FreeShipping
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("uses region from config for tax", () => {
    const taxFn = vi.fn(() => 100);
    const tax: TaxCalculator = { computeTaxCents: taxFn };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(widget, 1);
    cart.totals();
    expect(taxFn).toHaveBeenCalledWith(1000, "FR");
  });
});

// ── Async checkout() ─────────────────────────────────────────────
describe("Cart.checkout()", () => {
