  it("throws InventoryError on partial stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("w1");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({
      discountPolicy: makeDiscountPolicy(() => 0),
    });
    cart.add(widget, 1); // subtotal 1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(100); // 10% of 1000
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines discount + async tax + shipping", async () => {
    const discount = makeDiscountPolicy(() => 200);
    const shipping = makeShippingCalculator(() => 500);
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(widget, 1); // subtotal 1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // discounted = 800, tax = floor(800 * 0.0875) = 70, shipping = 500
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(70);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(800 + 70 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
