describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent discount results", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10), // 100
          new FixedAmountDiscountPolicy(200), // 200
        ],
        "sum",
      );
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });

    it("each child receives the original subtotal", () => {
      // Two 10% policies on 1000 → 100 + 100 = 200 (not 100 + 90)
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new PercentageDiscountPolicy(10),
        ],
        "sum",
      );
      expect(sut.computeDiscountCents(1000)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "sum",
      );
      expect(sut.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child results to zero before summing", () => {
      // NoDiscountPolicy returns 0, sum should still work
      const sut = new CompositeDiscountPolicy(
        [new NoDiscountPolicy(), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(sut.computeDiscountCents(500)).toBe(100);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const sut = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      // 10% of 1000 = 100 → remaining 900, then fixed 200 → remaining 700
      // total discount = 300
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(10),
          new FixedAmountDiscountPolicy(200),
        ],
        "chain",
      );
      expect(sut.computeDiscountCents(1000)).toBe(300);
    });

    it("ordering affects the result in chain mode", () => {
      // fixed 200 first on 1000 → remaining 800, then 10% of 800 = 80
      // total = 280
      const sut = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(200),
          new PercentageDiscountPolicy(10),
        ],
        "chain",
      );
      expect(sut.computeDiscountCents(1000)).toBe(280);
    });

    it("second child receives the reduced remaining", () => {
      // Two 50% policies: 50% of 1000 = 500, then 50% of 500 = 250
      // total = 750
      const sut = new CompositeDiscountPolicy(
        [
          new PercentageDiscountPolicy(50),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      expect(sut.computeDiscountCents(1000)).toBe(750);
    });

    it("stops reducing when remaining is zero", () => {
      const sut = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(1000),
          new PercentageDiscountPolicy(50),
        ],
        "chain",
      );
      // Fixed eats all 1000 → remaining 0 → 50% of 0 = 0
      expect(sut.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const sut = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(sut.computeDiscountCents(0)).toBe(0);
    });
  });
});
"}

