toolArgs.file_text:
import { describe, it, expect, vi } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine } from "../src/product.ts";

describe("NoTaxCalculator", () => {
  const sut = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [999_999, "FR"],
  ])("returns 0 for taxable=%i, region=%s", (taxable, region) => {
    expect(sut.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it.each([-0.01, 1.01, NaN, Infinity])(
      "rejects defaultRate %s",
      (rate) => {
        expect(() => new RegionalTaxCalculator({}, rate)).toThrow(RangeError);
      },
    );

    it("rejects out-of-range rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative rate in rates map", () => {
      expect(
        () => new RegionalTaxCalculator({ "US-CA": -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () =>
          new RegionalTaxCalculator({ "US-CA": 0.0875, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const sut = new RegionalTaxCalculator(
      { "US-CA": 0.0875, "US-OR": 0, FR: 0.2 },
      0.05,
    );

    it("looks up region-specific rate", () => {
      // 8.75% of 10000 = 875
      expect(sut.computeTaxCents(10000, "US-CA")).toBe(875);
    });

    it("falls back to default rate for unknown region", () => {
      // 5% of 10000 = 500
      expect(sut.computeTaxCents(10000, "DE")).toBe(500);
    });

    it("returns 0 for zero-rate region", () => {
      expect(sut.computeTaxCents(10000, "US-OR")).toBe(0);
    });

    it("rounds down to nearest cent", () => {
      // 20% of 333 = 66.6 → 66
      expect(sut.computeTaxCents(333, "FR")).toBe(66);
    });

    it("returns 0 for zero taxable", () => {
      expect(sut.computeTaxCents(0, "US-CA")).toBe(0);
    });

    it("returns 0 for negative taxable", () => {
      expect(sut.computeTaxCents(-100, "US-CA")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("computes tax using the provider rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    const result = await sut.computeTaxCents(1000, "US");
    expect(result).toBe(100);
    expect(provider.getRate).toHaveBeenCalledWith("US");
  });

  it("rounds down to nearest cent", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const sut = new AsyncTaxCalculator(provider);
    // 8.75% of 333 = 29.1375 → 29
    expect(await sut.computeTaxCents(333, "US-CA")).toBe(29);
  });

  it("returns 0 for zero taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    expect(await sut.computeTaxCents(0, "US")).toBe(0);
  });

  it("returns 0 for negative taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    expect(await sut.computeTaxCents(-100, "US")).toBe(0);
  });

  it("throws RangeError when provider returns rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(1.5),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns negative rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(-0.1),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("throws RangeError when provider returns NaN", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(NaN),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("network down")),
    };
    const sut = new AsyncTaxCalculator(provider);
    await expect(sut.computeTaxCents(1000, "US")).rejects.toThrow(
      "network down",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("sums weights across lines", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100, weightGrams: 500 }, quantity: 2 },
      { product: { id: "b", name: "B", unitPriceCents: 200, weightGrams: 300 }, quantity: 1 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(1300);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 3 },
    ];
    expect(totalLineWeightGrams(lines)).toBe(0);
  });

  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });
});

