import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

// ── Helpers ──────────────────────────────────────────────────────
const widget: Product = { id: "w1", name: "Widget", unitPriceCents: 1000 };
const gadget: Product = { id: "g1", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

function makeDiscountPolicy(fn: (s: number) => number): DiscountPolicy {
  return { computeDiscountCents: vi.fn(fn) };
}
function makeTaxCalculator(fn: (t: number, r: string) => number): TaxCalculator {
  return { computeTaxCents: vi.fn(fn) };
}
function makeShippingCalculator(fn: (l: readonly any[], s: number) => number): ShippingCalculator {
  return { computeShippingCents: vi.fn(fn) };
}

// ── Cart line management ─────────────────────────────────────────
describe("Cart line management", () => {
  it("adds a product and reports correct itemCount", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when the same product is added twice", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    cart.add(widget, 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.snapshot()).toHaveLength(1);
  });

  it("tracks separate products independently", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    expect(cart.itemCount).toBe(3);
    expect(cart.snapshot()).toHaveLength(2);
  });

  it("rejects zero quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 0)).toThrow(RangeError);
  });

  it("rejects negative quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "X", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });
});

describe("Cart.remove", () => {
  it("removes an existing product and returns true", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(cart.remove("w1")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false for unknown id", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });
});

describe("Cart.updateQuantity", () => {
  it("updates quantity for an existing line", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w1", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("removes the line when quantity is set to 0", () => {
    const cart = new Cart();
    cart.add(widget, 3);
    cart.updateQuantity("w1", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });

  it("throws for unknown product id", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
      "not in the cart",
    );
  });

  it("rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    expect(() => cart.updateQuantity("w1", 1.5)).toThrow(RangeError);
  });
});

describe("Cart.clear", () => {
  it("empties the cart", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.snapshot()).toHaveLength(0);
  });
});

describe("Cart.snapshot", () => {
  it("returns a deep copy that does not affect internal state", () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const snap = cart.snapshot();
    snap[0].quantity = 999;
    snap[0].product.unitPriceCents = 0;
    expect(cart.itemCount).toBe(2);
    expect(cart.totals().subtotalCents).toBe(2000);
  });
});

// ── Pricing pipeline ─────────────────────────────────────────────
describe("Cart.totals() pricing pipeline", () => {
  it("computes subtotal as sum of (price × qty)", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 2 × 1000
    cart.add(gadget, 1); // 1 × 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("applies discount then tax on discounted subtotal", () => {
    const discount = makeDiscountPolicy(() => 500);
    const tax = makeTaxCalculator((taxable) => Math.floor(taxable * 0.1));
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(widget, 2); // subtotal 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(500);
    // tax on 1500 at 10% = 150
    expect(totals.taxCents).toBe(150);
  });

  it("clamps discount to [0, subtotal] — negative discount becomes 0", () => {
    const discount = makeDiscountPolicy(() => -100);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount to [0, subtotal] — over-subtotal discount capped", () => {
    const discount = makeDiscountPolicy(() => 99999);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(widget, 1); // subtotal 1000
    expect(cart.totals().discountCents).toBe(1000);
  });

  it("clamps negative tax to 0", () => {
    const tax = makeTaxCalculator(() => -50);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping = makeShippingCalculator(() => -50);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("passes discounted subtotal to shipping calculator", () => {
    const discount = makeDiscountPolicy(() => 300);
    const shippingFn = vi.fn(() => 500);
    const shipping: ShippingCalculator = {
      computeShippingCents: shippingFn,
    };
    const cart = new Cart({ discountPolicy: discount, shippingCalculator: shipping });
    cart.add(widget, 1); // subtotal 1000, discounted = 700
    cart.totals();
    expect(shippingFn).toHaveBeenCalledWith(expect.any(Array), 700);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount = makeDiscountPolicy(() => 200);
    const tax = makeTaxCalculator(() => 80);
    const shipping = makeShippingCalculator(() => 500);
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(widget, 1); // subtotal 1000
    const totals = cart.totals();
    // discounted = 800, total = 800 + 80 + 500 = 1380
    expect(totals.totalCents).toBe(1380);
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("uses defaults when no config is provided", () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const totals = cart.totals();
    // NoDiscount, NoTax, FreeShipping
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });

  it("uses region from config for tax", () => {
    const taxFn = vi.fn(() => 100);
    const tax: TaxCalculator = { computeTaxCents: taxFn };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(widget, 1);
    cart.totals();
    expect(taxFn).toHaveBeenCalledWith(1000, "FR");
  });
});

// ── Async checkout() ─────────────────────────────────────────────
describe("Cart.checkout()", () => {
  it("returns totals and lines for a basic checkout", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 2 × 1500
    expect(result.lines[0].product.unitPriceCents).toBe(1500);
  });

  it("validates inventory and passes on success", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
    expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
  });

  it("throws InventoryError when item unavailable", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 0,
        reason: "sold out",
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("w1");
      expect(err.requested).toBe(2);
      expect(err.available).toBe(0);
    }
  });

  it("throws InventoryError on partial stock denial", async () => {
    const cart = new Cart();
    cart.add(widget, 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
    try {
      await cart.checkout({ inventoryChecker });
    } catch (e) {
      const err = e as InventoryError;
      expect(err.productId).toBe("w1");
      expect(err.requested).toBe(5);
      expect(err.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax calculation", async () => {
    const cart = new Cart({
      discountPolicy: makeDiscountPolicy(() => 0),
    });
    cart.add(widget, 1); // subtotal 1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(100); // 10% of 1000
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("combines discount + async tax + shipping", async () => {
    const discount = makeDiscountPolicy(() => 200);
    const shipping = makeShippingCalculator(() => 500);
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(widget, 1); // subtotal 1000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // discounted = 800, tax = floor(800 * 0.0875) = 70, shipping = 500
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(70);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(800 + 70 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("checks inventory for each line — first denial wins", async () => {
    const cart = new Cart();
    cart.add(widget, 1);
    cart.add(gadget, 1);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true, availableQuantity: 10 })
        .mockResolvedValueOnce({ available: false, reason: "gadget gone" }),
    };
    await expect(cart.checkout({ inventoryChecker })).rejects.toThrow(
      InventoryError,
    );
  });

  it("combines price refresh with inventory check", async () => {
    const cart = new Cart();
    cart.add(widget, 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker });
    expect(result.totals.subtotalCents).toBe(1000); // 2 × 500
    expect(inventoryChecker.check).toHaveBeenCalledWith("w1", 2);
  });

  it("empty cart checks out with zero totals", async () => {
    const cart = new Cart();
    const result = await cart.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });
});

